body.script:
(() => {
  const mount = document.getElementById('velora-mount');
  const status = document.getElementById('velora-status');
  const frame = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
  frame.setAttribute('title', 'Velora');
  frame.setAttribute('style', 'position:absolute;inset:0;display:block;width:100%;height:100%;border:0;background:#161a20');
  frame.setAttribute('allow', 'fullscreen; clipboard-read; clipboard-write; autoplay; gamepad; picture-in-picture');
  frame.setAttribute('allowfullscreen', 'allowfullscreen');
  frame.addEventListener('load', () => status.remove(), { once: true });
  frame.setAttribute('src', 'https://ixl.pozzi-pozzi.workers.dev/');
  mount.appendChild(frame);
})();
